/** A string in `lang` (English when the language or key is unknown), with {name} slots filled. */
export function tr(key, lang = "en", vars = {}) {
  const text = (STRINGS[lang] || STRINGS.en)[key] ?? STRINGS.en[key] ?? key;
  return text.replace(/\{([a-z_]{1,20})\}/g, (whole, name) => (vars[name] === undefined || vars[name] === null ? "" : String(vars[name])));
}

/** The plain reason a briefing has no audio or failed, from its `error` word. */
export function reasonText(error, lang = "en") {
  const key = `reason_${error}`;
  return (STRINGS.en[key] ? tr(key, lang) : tr("reason_other", lang, { error: String(error || "unknown").slice(0, 60) }));
}
